    "p5.Biquad": {
      "name": "p5.Biquad",
      "shortname": "Biquad",
      "classitems": [],
      "plugins": [],
      "extensions": [],
      "plugin_for": [],
      "extension_for": [],
      "module": "p5.sound",
      "submodule": "p5.sound",
      "namespace": "",
      "file": "src/effects/Biquad.js",
      "line": 11,
      "description": "Filter the frequency range of a sound.",
      "is_constructor": 1,
      "extends": "p5soundNode",
      "params": [
        {
          "name": "cutoff",
          "description": "cutoff frequency of the filter, a value between 0 and 24000.",
          "type": "Number",
          "optional": true
        },
        {
          "name": "type",
          "description": "filter type. Options: \"lowpass\", \n                       \"highpass\", \"bandpass\", \"lowshelf\",\n                       \"highshelf\", \"notch\", \"allpass\", \n                       \"peaking\"",
          "type": "String",
          "optional": true
        }
      ],
      "example": [
        "\n<div>\n<code>\nlet fft, noise, filterEffect;\n\nfunction setup() {\n  let cnv = createCanvas(100,100);\n  cnv.mousePressed(makeNoise);\n  fill(255, 0, 255);\n\n  filterEffect = new p5.BandPass();\n  noise = new p5.Noise();\n  noise.disconnect();\n  noise.connect(filterEffect);\n  \n  fft = new p5.FFT(128);\n  filterEffect.connect(fft);\n}\n\nfunction draw() {\n  background(220);\n\n  // set the BandPass frequency based on mouseX\n  let freq = map(mouseX, 0, width, 20, 10000);\n  freq = constrain(freq, 0, 22050);\n  filterEffect.freq(freq);\n  // give the filter a narrow band (lower res = wider bandpass)\n  filterEffect.res(20);\n\n  // draw filtered spectrum\n  let spectrum = fft.analyze();\n  \n  noStroke();\n  fill(0, 0, 0);\n  for (let i = 0; i < spectrum.length; i++) {\n    let x = map(i, 0, spectrum.length, 0, width);     \n    let h = -height + map(spectrum[i], 0, 0.02, height, 0);\n    rect(x, height, width / spectrum.length, h )\n  }\n  if (!noise.started) {\n    text('click and drag to change filter\\'s center frequency', 10, 20, width - 20);\n  } else {\n    text('Frequency: ' + round(freq)+'Hz', 20, 20, width - 20);\n  }\n}\n\nfunction makeNoise() {\n  noise.start();\n  noise.amp(0.9, 0.1);\n}\n\nfunction mouseReleased() {\n  noise.amp(0, 0.1);\n}\n</code>\n</div>"
      ]
    },
